  "output_head": "<!DOCTYPE html>
<!-- Quizzy design: "Moderator / Quiz" frame, exported from the design file. Static: nothing on this page is interactive. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quizzy · Quiz page</title>
<link rel="stylesheet" href="quizzy.css">
</head>
<body>
  <!-- Layer: Header -->
  <header class="admin-header">
    <span class="logo"><span class="logo__mark">?</span>Quizzy</span>
